def bundle_digest(bundle: KnowledgeBundle) -> str:
    """sha256 of the knowledge content; manifest and precomputed vectors are excluded."""
    content = {
        "documents": [record.model_dump(mode="json") for record in bundle.documents],
        "sections": [record.model_dump(mode="json") for record in bundle.sections],
        "glossary": [entry.model_dump(mode="json") for entry in bundle.glossary],
        "colloquial_mappings": [
            mapping.model_dump(mode="json") for mapping in bundle.colloquial_mappings
        ],
    }
    return sha256_hex(canonical_json(content))


def build_snapshot(bundle: KnowledgeBundle) -> CorpusSnapshot:
    """Rows for one release of `bundle`. Raises CorpusImportError on broken references."""
    records = {record.key: record for record in bundle.documents}
    problems = [
        f"sections.jsonl: section {section.key} references unknown document "
        f"{section.document_key}"
        for section in bundle.sections
        if section.document_key not in records
    ]
    if problems:
        raise CorpusImportError("; ".join(problems))

    manifest_collection = bundle.manifest.collection
    # Without an owner the collection is the public system corpus. A collection a user
    # or organization created keeps its owner and visibility: the repository upserts
    # on the key and never overwrites them.
    collection = Collection(
        id=collection_id_for(manifest_collection.key),
        key=manifest_collection.key,
        title=manifest_collection.title,
        visibility=Visibility.PUBLIC,
    )
    documents = [
        Document(
            id=document_id_for(collection.id, record.key),
            collection_id=collection.id,
            key=record.key,
            title=record.title,
            source_title=record.source.title,
        )
"""Text helpers shared by the corpus and retrieval domains."""

import re
import unicodedata

ELLIPSIS = "…"
_WHITESPACE_RE = re.compile(r"\s+")


def normalize_text(text: str) -> str:
    """NFC, unify line endings, drop trailing spaces per line and outer blank lines."""
    unified = (
        unicodedata.normalize("NFC", text).replace("\r\n", "\n").replace("\r", "\n")
    )
    lines = [line.rstrip() for line in unified.split("\n")]
    start = 0
    end = len(lines)
    while start < end and not lines[start]:
        start += 1
    while end > start and not lines[end - 1]:
        end -= 1
    return "\n".join(lines[start:end])


def _is_table_rule(line: str) -> bool:
    stripped = line.strip()
    return stripped.startswith("|") and "-" in stripped and not stripped.strip("|-: ")


def make_snippet(text: str, max_chars: int) -> str:
    """One-line preview: no table pipes or rules, cut at a word boundary with "…"."""
    if max_chars < 1:
        raise ValueError("max_chars must be at least 1")
    kept = [line for line in text.splitlines() if not _is_table_rule(line)]
    flat = _WHITESPACE_RE.sub(" ", " ".join(kept).replace("|", " ")).strip()
    if len(flat) <= max_chars:
        return flat
    head = flat[: max_chars - 1]
    if flat[max_chars - 1] != " ":
        boundary = head.rfind(" ")
        if boundary > 0:
            head = head[:boundary]
    return head.rstrip() + ELLIPSIS

